"""Writes tvos/Meowio/BuildSecrets.swift from repository secrets.

Values come from the environment (NUVIO_SUPABASE_URL, NUVIO_SUPABASE_ANON_KEY, TRAKT_CLIENT_ID,
TRAKT_CLIENT_SECRET). Anything missing is looked up in the Android TV local.properties secret
(TV_LOCAL_PROPERTIES_BASE64). Nothing is printed, so values never reach the build log.
"""
import base64
import os
import sys

props = {}
raw = os.environ.get("TV_LOCAL_PROPERTIES_BASE64", "").strip()
if raw:
    try:
        for line in base64.b64decode(raw).decode("utf-8", "replace").splitlines():
            line = line.strip()
            if line and not line.startswith("#") and "=" in line:
                k, v = line.split("=", 1)
                props[k.strip()] = v.strip()
    except Exception:
        props = {}


def value(name):
    v = os.environ.get(name, "").strip() or props.get(name, "").strip()
    # Keep it a plain Swift string literal.
    return "".join(c for c in v if c.isprintable() and c not in '"\\')


fields = {
    "supabaseURL": value("NUVIO_SUPABASE_URL"),
    "supabaseAnonKey": value("NUVIO_SUPABASE_ANON_KEY"),
    "traktClientId": value("TRAKT_CLIENT_ID"),
    "traktClientSecret": value("TRAKT_CLIENT_SECRET"),
}

out = ["/// Generated by the Apple build workflow from repository secrets.", "enum BuildSecrets {"]
for k, v in fields.items():
    out.append(f'    static let {k} = "{v}"')
out.append("}")
with open(sys.argv[1], "w") as f:
    f.write("\n".join(out) + "\n")
print("Account server:", "set" if fields["supabaseURL"] else "not set")
print("Trakt app:", "set" if fields["traktClientId"] and fields["traktClientSecret"] else "not set")
